/**
 * Plugin for :::file-tree directive (Vuepress Plume-inspired design).
 *
 * Uses vscode-icons (via @iconify-json/vscode-icons) for per-file-type icons.
 * Icon data is generated by scripts/generate-file-icons.mjs.
 *
 * Remark phase: parses mdast children and replaces the containerDirective
 * with a raw html node containing the pre-rendered file tree HTML.
 * Folder icons only render the closed SVG. Client-side JS resolves the
 * open icon from folder-open-icons.json and swaps SVGs on toggle.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { visit } from "unist-util-visit";

const __dirname = dirname(fileURLToPath(import.meta.url));

let iconData;
try {
	iconData = JSON.parse(
		readFileSync(join(__dirname, "file-icons.json"), "utf-8"),
	);
} catch {
	iconData = {
		icons: {
			"default-file": {
				body: '<path fill="#c5c5c5" d="M20.414 2H5v28h22V8.586ZM7 28V4h12v6h6v18Z"/>',
				viewBox: "0 0 32 32",
			},
			"default-folder": {
				body: '<path fill="#dcb67a" d="M2 4v24h28V8H14l-4-4z"/>',
				viewBox: "0 0 32 32",
			},
			"default-folder-opened": {
				body: '<path fill="#dcb67a" d="M2 4v24h28V8H14l-4-4z"/><path fill="#e8d5a3" d="M2 12v16h28V12z"/>',
				viewBox: "0 0 32 32",
			},
		},
		fileMap: {},
		folderMap: {},
		folderOpenMap: {},
		defaultFile: "default-file",
		defaultFolder: "default-folder",
		defaultFolderOpen: "default-folder-opened",
		chevron: {
			body: '<path fill="currentColor" d="m5.157 13.069l4.611-4.685a.546.546 0 0 0 0-.768L5.158 2.93a.55.55 0 0 1 0-.771a.53.53 0 0 1 .759 0l4.61 4.684a1.65 1.65 0 0 1 0 2.312l-4.61 4.684a.53.53 0 0 1-.76 0a.55.55 0 0 1 0-.771"/>',
			viewBox: "0 0 16 16",
		},
		ellipsis: {
			body: '<circle fill="#94a3b8" cx="4" cy="8" r="1.5"/><circle fill="#94a3b8" cx="8" cy="8" r="1.5"/><circle fill="#94a3b8" cx="12" cy="8" r="1.5"/>',
			viewBox: "0 0 16 16",
		},
		defaultIcon: "default-file",
	};
}

function resolveFileIcon(filename) {
	const lower = filename.toLowerCase();
	if (iconData.fileMap[lower]) return iconData.fileMap[lower];
	const base = filename.split("/").pop() || filename;
	const baseLower = base.toLowerCase();
	if (iconData.fileMap[baseLower]) return iconData.fileMap[baseLower];
	const ext = base.split(".").pop()?.toLowerCase() || "";
	if (iconData.fileMap[ext]) return iconData.fileMap[ext];
	return iconData.defaultFile || iconData.defaultIcon;
}

function resolveFolderIcon(folderName, isOpen) {
	const lower = folderName.toLowerCase();
	const closedName = iconData.folderMap?.[lower];
	if (closedName && iconData.icons[closedName]) {
		if (isOpen) {
			const openName = iconData.folderOpenMap?.[closedName];
			if (openName && iconData.icons[openName]) return openName;
		}
		return closedName;
	}
	return isOpen
		? iconData.defaultFolderOpen || iconData.defaultFolder
		: iconData.defaultFolder;
}

function getIconEntry(iconName) {
	if (iconName && iconData.icons[iconName]) {
		return iconData.icons[iconName];
	}
	return (
		iconData.icons[iconData.defaultFile || iconData.defaultIcon] ||
		iconData.icons["default-file"]
	);
}

// --- MDAST parsing ---

function mdastText(node) {
	if (!node) return "";
	if (node.type === "text" || node.type === "inlineCode") return node.value;
	if (Array.isArray(node.children))
		return node.children.map(mdastText).join("");
	return "";
}

function parseItemText(text) {
	let name = text.trim();
	let comment = "";
	let diffType = null;

	const commentMatch = name.match(/\s+#\s+(.+)$/);
	if (commentMatch) {
		comment = commentMatch[1].trim();
		name = name.slice(0, name.length - commentMatch[0].length).trim();
	}

	if (name.startsWith("++ ")) {
		diffType = "add";
		name = name.slice(3).trim();
	} else if (name.startsWith("— ") || name.startsWith("-- ")) {
		diffType = "remove";
		name = name.slice(name.startsWith("— ") ? 2 : 3).trim();
	}

	const isFolder = name.endsWith("/");
	if (isFolder) name = name.slice(0, -1);
	const isEllipsis = name === "..." || name === "…";

	return { name, comment, diffType, isFolder, isEllipsis };
}

function parseMdastListItem(li) {
	let text = "";
	let childList = null;

	for (const child of li.children || []) {
		if (child.type === "paragraph" && !childList) {
			text = mdastText(child);
		} else if (child.type === "list") {
			childList = child;
		} else if (child.type === "text" && !text) {
			text = child.value;
		}
	}

	const parsed = parseItemText(text);
	const node = { ...parsed, children: [] };

	if (childList) {
		for (const child of childList.children || []) {
			if (child.type === "listItem") {
				node.children.push(parseMdastListItem(child));
			}
		}
	}

	return node;
}

function parseMdastList(list) {
	const nodes = [];
	for (const child of list.children || []) {
		if (child.type === "listItem") {
			nodes.push(parseMdastListItem(child));
		}
	}
	return nodes;
}

// --- HTML rendering ---

function escapeHtml(str) {
	return str
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;");
}

function svgHtml(iconEntry, extraClass) {
	const body = typeof iconEntry === "string" ? iconEntry : iconEntry.body;
	const viewBox =
		typeof iconEntry === "string" ? "0 0 32 32" : iconEntry.viewBox;
	return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}"${extraClass ? ` class="${extraClass}"` : ""}>${body}</svg>`;
}

function buildNodeHtml(node, level) {
	const { name, comment, diffType, isFolder, isEllipsis, children } = node;
	const levelStyle = `--file-tree-level: -${level};`;

	if (isEllipsis) {
		return `<div class="vp-file-tree-node"><p class="vp-file-tree-info file" style="${levelStyle}"><span class="vp-file-tree-diff-indicator"></span><span class="vp-file-tree-arrow-spacer"></span><span class="vp-file-tree-icon vp-file-tree-ellipsis">${svgHtml(iconData.ellipsis)}</span><span class="vp-file-tree-name vp-file-tree-ellipsis-text">…</span></p></div>`;
	}

	const infoClasses = ["vp-file-tree-info", isFolder ? "folder" : "file"];
	if (diffType) {
		infoClasses.push("diff", diffType === "add" ? "add" : "remove");
	}

	let infoKids = "";

	if (diffType) {
		const indicatorClass = `vp-file-tree-diff-indicator ${diffType === "add" ? "add" : "remove"}`;
		const indicatorText = diffType === "add" ? "+" : "−";
		infoKids += `<span class="${indicatorClass}">${indicatorText}</span>`;
	} else {
		infoKids += `<span class="vp-file-tree-diff-indicator"></span>`;
	}

	if (isFolder) {
		infoKids += `<span class="vp-file-tree-arrow">${svgHtml(iconData.chevron, "vp-file-tree-arrow-icon")}</span>`;
		const closedIconName = resolveFolderIcon(name, false);
		const closedEntry = getIconEntry(closedIconName);
		infoKids += `<span class="vp-file-tree-icon">${svgHtml(closedEntry)}</span>`;
	} else {
		infoKids += `<span class="vp-file-tree-arrow-spacer"></span>`;
		const iconName = resolveFileIcon(name);
		const iconEntry = getIconEntry(iconName);
		infoKids += `<span class="vp-file-tree-icon">${svgHtml(iconEntry)}</span>`;
	}

	infoKids += `<span class="vp-file-tree-name ${isFolder ? "folder" : "file"}">${escapeHtml(name)}</span>`;

	if (comment) {
		infoKids += `<span class="vp-file-tree-comment">${escapeHtml(comment)}</span>`;
	}

	if (!isFolder) {
		return `<div class="vp-file-tree-node"><p class="${infoClasses.join(" ")}" style="${levelStyle}">${infoKids}</p></div>`;
	}

	if (children.length === 0) {
		return `<div class="vp-file-tree-node"><p class="${infoClasses.join(" ")}" style="${levelStyle}">${infoKids}</p></div>`;
	}

	const childLevel = level + 1;
	const childHtml = children.map((c) => buildNodeHtml(c, childLevel)).join("");
	const isOpen = level === 0;
	if (isOpen) {
		infoClasses.push("expanded");
	}

	return `<div class="vp-file-tree-node"><details${isOpen ? " open" : ""}><summary><p class="${infoClasses.join(" ")}" style="${levelStyle}">${infoKids}</p></summary><div class="vp-file-tree-group" style="--file-tree-level: -${childLevel};">${childHtml}</div></details></div>`;
}

function buildFileTreeHtml(nodes) {
	return nodes.map((n) => buildNodeHtml(n, 0)).join("");
}

export function remarkFileTree() {
	return (tree) => {
		visit(tree, "containerDirective", (node, index, parent) => {
			if (node.name !== "file-tree") return;
			if (!parent || typeof index !== "number") return;

			const listChild = (node.children || []).find((c) => c.type === "list");

			if (!listChild) {
				parent.children[index] = {
					type: "html",
					value: '<div class="vp-file-tree"></div>',
				};
				return;
			}

			const treeNodes = parseMdastList(listChild);
			const html = buildFileTreeHtml(treeNodes);

			parent.children[index] = {
				type: "html",
				value: `<div class="vp-file-tree">${html}</div>`,
			};
		});
	};
}

export function rehypeFileTreeV3() {
	return () => {};
}
